<?php
require __DIR__.'/../src/bootstrap.php';$user=requireLogin();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requirePost();try{SalesPointService::save($user,$_POST,intField($_POST,'id'));flash('Đã lưu điểm bán.');redirect('/sales-points.php');}catch(DomainException $e){$error=ERROR_LABELS[$e->getMessage()]??'Không lưu được điểm bán. Kiểm tra mã, tên, loại và kho phụ trách.';}catch(Throwable $e){error_log('Sales point save failed: '.$e->getMessage());$error='Không lưu được điểm bán. Mã có thể đã tồn tại.';}}
$points=Store::all('sales_points');if($user['role']==='sales_user')$points=array_values(array_filter($points,fn($p)=>canAccessSalesPoint($user,(int)$p['id'])));$warehouses=Store::all('warehouses');$editing=isset($_GET['edit'])?Store::find('sales_points',intField($_GET,'edit')??0):null;
// Tuyến giao của mọi điểm bán: [point_id => [warehouse_id, ...]] (không gồm kho chính).
$extraRoutes=[];foreach(Database::connection()->query('SELECT sales_point_id,warehouse_id FROM sales_point_warehouses WHERE NOT is_primary ORDER BY warehouse_id') as $r)$extraRoutes[(int)$r['sales_point_id']][]=(int)$r['warehouse_id'];
$selectedRoutes=$_SERVER['REQUEST_METHOD']==='POST'?array_map('intval',(array)($_POST['route_warehouse_ids']??[])):($editing?($extraRoutes[$editing['id']]??[]):[]);
$title='Điểm bán';$active='sales-points';require __DIR__.'/../templates/header.php';
?>
<header class="page-head"><div><h1>Điểm bán</h1><p>Đại lý, cửa hàng và siêu thị thuộc phạm vi kho địa điểm.</p></div><a class="button" href="/sales-orders.php">Đơn phân phối</a></header>
<?php if($error):?><div class="error-summary" role="alert"><?=e($error)?></div><?php endif;?>
<?php if(canManageCatalog($user)):?><section class="card"><h2><?=$editing?'Sửa điểm bán':'Thêm điểm bán'?></h2><form method="post" class="form"><?=csrfInput()?><input type="hidden" name="id" value="<?=e((string)($editing['id']??''))?>"><div class="form-row"><label class="form-field">Mã<input name="code" required maxlength="40" value="<?=e($editing['code']??'')?>"></label><label class="form-field form-field--wide">Tên<input name="name" required maxlength="200" value="<?=e($editing['name']??'')?>"></label><label class="form-field">Loại<select name="point_type" required><?php foreach(SALES_POINT_TYPES as $k=>$v):?><option value="<?=$k?>" <?=($editing['point_type']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label class="form-field">Kho phụ trách<select name="primary_warehouse_id" required><?php foreach($warehouses as $w): if(!$w['active'])continue;?><option value="<?=$w['id']?>" <?=($editing['primary_warehouse_id']??0)===$w['id']?'selected':''?>><?=e($w['code'].' · '.$w['name'])?></option><?php endforeach;?></select></label><label class="form-field form-field--wide">Địa chỉ<input name="address" value="<?=e($editing['address']??'')?>"></label><label class="form-field">Người liên hệ<input name="contact_name" maxlength="160" value="<?=e($editing['contact_name']??'')?>"></label><label class="form-field">Điện thoại<input name="phone" maxlength="40" value="<?=e($editing['phone']??'')?>"></label><label class="form-field">Email<input type="email" name="email" maxlength="160" value="<?=e($editing['email']??'')?>"></label><label class="form-field form-field--wide">Ghi chú<input name="note" maxlength="2000" value="<?=e($editing['note']??'')?>"></label><label><input type="checkbox" name="active" <?=!isset($editing['active'])||$editing['active']?'checked':''?>> Đang hoạt động</label></div>
<fieldset class="form-field form-field--wide"><legend>Kho giao thêm <span class="muted">(ngoài kho phụ trách; nhân viên các kho này được lập đơn giao cho điểm bán)</span></legend><div class="form-row"><?php $currentRoutes=$editing?($extraRoutes[$editing['id']]??[]):[]; foreach($warehouses as $w): if(!$w['active']&&!in_array($w['id'],$currentRoutes,true))continue;?><label><input type="checkbox" name="route_warehouse_ids[]" value="<?=$w['id']?>" <?=in_array($w['id'],$selectedRoutes,true)?'checked':''?>> <?=e($w['code'].' · '.$w['name'])?><?=$w['active']?'':' <span class="muted">(ngừng hoạt động)</span>'?></label><?php endforeach;?></div></fieldset>
<button class="button">Lưu</button></form></section><?php endif;?>
<section class="card table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Điểm bán</th><th>Loại</th><th>Kho phụ trách</th><th>Liên hệ</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($points as $p):?><tr><td><?=e($p['code'])?></td><td><a class="text-link" href="/sales-point.php?id=<?=$p['id']?>"><strong><?=e($p['name'])?></strong></a><br><span class="muted"><?=e($p['address'])?></span></td><td><?=e(SALES_POINT_TYPES[$p['point_type']]??$p['point_type'])?></td><td><?=e(warehouseName($p['primary_warehouse_id']))?><?php if(!empty($extraRoutes[$p['id']])):?><br><span class="muted">+ <?=e(implode(', ',array_map('warehouseName',$extraRoutes[$p['id']])))?></span><?php endif;?></td><td><?=e(trim($p['contact_name'].' '.$p['phone']))?><br><span class="muted"><?=e($p['email'])?></span></td><td><?=$p['active']?'Đang hoạt động':'Ngừng hoạt động'?></td><td><a class="text-link" href="/sales-point.php?id=<?=$p['id']?>">Chi tiết</a><?php if(canManageCatalog($user)):?> · <a class="text-link" href="/sales-points.php?edit=<?=$p['id']?>">Sửa</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<?php require __DIR__.'/../templates/footer.php';
